// Safaricom callback shape:
// { Body: { stkCallback: { MerchantRequestID, CheckoutRequestID, ResultCode, ResultDesc, CallbackMetadata?: { Item: [...] } } } }
const body = $json.body || $json;
const cb = body?.Body?.stkCallback;
if (!cb) throw new Error('Not a valid STK callback payload');

const resultCode = cb.ResultCode;
const isSuccess = resultCode === 0;

const meta = {};
if (cb.CallbackMetadata?.Item) {
  for (const item of cb.CallbackMetadata.Item) {
    meta[item.Name] = item.Value;
  }
}

return [{
  json: {
    checkout_request_id: cb.CheckoutRequestID,
    merchant_request_id: cb.MerchantRequestID,
    result_code: resultCode,
    result_desc: cb.ResultDesc,
    status: isSuccess ? 'success' : 'failed',
    amount: meta.Amount || null,
    mpesa_receipt_number: meta.MpesaReceiptNumber || null,
    transaction_date: meta.TransactionDate ? String(meta.TransactionDate) : null,
    phone_number: meta.PhoneNumber ? String(meta.PhoneNumber) : null,
    raw: cb
  }
}];

// Build a confirmation message - plug in Email/SMS/WhatsApp/Slack after this
const tx = $('Parse Callback').item.json;
const row = $('Update Transaction').item.json;

return [{
  json: {
    to: tx.phone_number,
    subject: 'Payment Received',
    message: `Hi! We received your payment of KES ${tx.amount}. M-Pesa receipt: ${tx.mpesa_receipt_number}. Ref: ${row?.reference || 'N/A'}. Thank you!`,
    receipt: tx.mpesa_receipt_number,
    amount: tx.amount,
    reference: row?.reference
  }
}];

const tx = $('Parse Callback').item.json;
return [{
  json: {
    to_notify: 'ops@yourcompany.co.ke',
    reason: tx.result_desc,
    code: tx.result_code,
    checkout_request_id: tx.checkout_request_id
  }
}];
